import { Mesh, Group, BoxGeometry, PlaneGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Color } from 'three/webgpu';
import { uv, mix, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const T = ctx.THREE;
  const group = new Group();
  group.userData.handlers = {};
  const cleanups = [];
  const timelines = [];

  const accent = new Color('#ff2a38');
  const ink = new Color('#16161d');
  const surface = new Color('#0b0b10');
  const paper = new Color('#e8ecf2');

  // Inner card container (animated, adapter sets outer group transform)
  const card = new Group();
  group.add(card);

  // Backdrop backing plane — vertical gradient surface -> ink, local to card to avoid void directly behind
  const bdGeo = new PlaneGeometry(3.4, 3.8);
  const bdMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 1 });
  bdMat.colorNode = mix(uniform(ink), uniform(surface), uv().sub(0.5).y.add(0.5).clamp(0, 1));
  bdMat.toneMapped = false;
  const backdrop = new Mesh(bdGeo, bdMat);
  backdrop.position.set(0, 0, -0.45);
  card.add(backdrop);
  cleanups.push(() => { bdGeo.dispose(); bdMat.dispose(); });

  // Main panel — extruded 3D card
  const panelGeo = new BoxGeometry(2.2, 2.85, 0.12);
  const panelMat = new MeshStandardNodeMaterial({
    color: surface,
    roughness: 0.55,
    metalness: 0.4,
    emissive: new Color(0x05060a),
    emissiveIntensity: 0.4,
  });
  const panel = new Mesh(panelGeo, panelMat);
  panel.position.set(0, 0, -0.06);
  card.add(panel);
  cleanups.push(() => { panelGeo.dispose(); panelMat.dispose(); });

  // Inner image well — recessed darker plane where the gear sits
  const wellGeo = new BoxGeometry(2.02, 2.18, 0.06);
  const wellMat = new MeshStandardNodeMaterial({
    color: new Color('#06060a'),
    roughness: 0.65,
    metalness: 0.25,
  });
  const well = new Mesh(wellGeo, wellMat);
  well.position.set(0, 0.28, 0.02);
  card.add(well);
  cleanups.push(() => { wellGeo.dispose(); wellMat.dispose(); });

  // Thin inner bezel frame (paper-tinted metallic edge)
  const bezelMat = new MeshStandardNodeMaterial({
    color: new Color('#1c1c26'),
    roughness: 0.45,
    metalness: 0.55,
  });
  const bezelTop = new Mesh(new BoxGeometry(2.06, 0.04, 0.1), bezelMat);
  bezelTop.position.set(0, 1.37, 0.04);
  const bezelBot = new Mesh(new BoxGeometry(2.06, 0.04, 0.1), bezelMat);
  bezelBot.position.set(0, -0.81, 0.04);
  const bezelL = new Mesh(new BoxGeometry(0.04, 2.22, 0.1), bezelMat);
  bezelL.position.set(-1.01, 0.28, 0.04);
  const bezelR = bezelL.clone();
  bezelR.position.x = 1.01;
  card.add(bezelTop, bezelBot, bezelL, bezelR);
  cleanups.push(() => { bezelMat.dispose(); });

  // Caption strip — bottom band of the card
  const stripGeo = new BoxGeometry(2.2, 0.52, 0.08);
  const stripMat = new MeshStandardNodeMaterial({
    color: ink,
    roughness: 0.6,
    metalness: 0.3,
  });
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.set(0, -1.165, 0.04);
  card.add(strip);
  cleanups.push(() => { stripGeo.dispose(); stripMat.dispose(); });

  // Accent edge line at top of caption strip (signal red, emissive)
  const edgeGeo = new BoxGeometry(1.6, 0.045, 0.1);
  const edgeMat = new MeshStandardNodeMaterial({
    color: accent,
    roughness: 0.35,
    metalness: 0.1,
    emissive: accent,
    emissiveIntensity: 1.4,
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(-0.3, -0.905, 0.07);
  card.add(edge);
  cleanups.push(() => { edgeGeo.dispose(); edgeMat.dispose(); });

  // Gear mesh from GLB sits in the image well
  let gearRef = null;
  gearRef = null;
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const m = gltf.scene ? gltf.scene : gltf;
    m.traverse((o) => {
      if (o.isMesh) {
        o.material = new MeshStandardNodeMaterial({
          color: new Color('#9aa0ad'),
          roughness: 0.4,
          metalness: 0.95,
          emissive: new Color(0x0a0c10),
          emissiveIntensity: 0.25,
        });
        cleanups.push(() => o.material.dispose());
      }
    });
    // Fit gear into the well
    m.scale.setScalar(0.42);
    m.position.set(0, 0.18, 0.18);
    m.rotation.set(-0.18, 0.4, 0);
    card.add(m);
    gearRef = m;

    // Slow idle breathing on gear
    const idle = gsap.to(m.rotation, {
      y: 0.4 + 0.25,
      duration: 6,
      ease: 'sine.inOut',
      yoyo: true,
      repeat: -1,
    });
    timelines.push(idle);
  }).catch(() => { gearRef = null; });

  // Local accent rim light (scene provides ambient 0.6 + key 1.2)
  const rim = new T.DirectionalLight(0xff2a38, 0.7);
  rim.position.set(-3, 1.5, -2.5);
  card.add(rim);
  const backFill = new T.DirectionalLight(0x8aa0bd, 0.35);
  backFill.position.set(-2, -1.5, 2);
  card.add(backFill);
  cleanups.push(() => { card.remove(rim, backFill); });

  // Entrance: rise-in + weighted-settle
  card.position.y = 0.4;
  card.scale.setScalar(0.96);
  const enterY = gsap.to(card.position, { y: 0, duration: 0.7, ease: 'power3.out', delay: 0.1 });
  const enterS = gsap.to(card.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.7, ease: 'power3.out', delay: 0.1 });
  gsap.to(card.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out', delay: 0.8 });
  timelines.push(enterY, enterS);

  // Hover / click handlers
  let hoverActive = false;
  let pressTl = null;
  group.userData.handlers.hover = (active) => {
    hoverActive = !!active;
    gsap.to(card.position, { y: active ? 0.15 : 0, duration: 0.4, ease: 'power3.out' });
    gsap.to(card.rotation, { x: active ? -0.05 : 0, y: active ? 0.04 : 0, duration: 0.3, ease: 'power2.out' });
    gsap.to(edgeMat, { emissiveIntensity: active ? 2.1 : 1.4, duration: 0.35, ease: 'power2.out' });
  };
  group.userData.handlers.focus = (active) => {
    gsap.to(edgeMat, { emissiveIntensity: active ? 2.0 : (hoverActive ? 2.1 : 1.4), duration: 0.3 });
  };
  group.userData.handlers.click = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(card.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.in' });
    pressTl.to(card.scale, { x: 1, y: 1, z: 1, duration: 0.22, ease: 'back.out(2.2)' });
    timelines.push(pressTl);
    try { ctx.emit('hub-home.select', { source: 'thumbnail-card' }); } catch (_) {}
  };

  // Cleanup
  group.userData.cleanup = () => {
    timelines.forEach((t) => { try { t.kill(); } catch (_) {} });
    cleanups.forEach((fn) => { try { fn(); } catch (_) {} });
    for (let i = card.children.length - 1; i >= 0; i--) card.remove(card.children[i]);
  };

  return group;
}
